"""Careful client for the local order service (working script, kept out of /workspace)."""
import collections
import datetime as dt
import http.client
import json
import os
import socket
import time
import urllib.error
import urllib.request
from email.utils import parsedate_to_datetime

BASE = "http://localhost:8080"
WORK = "/tmp/recon_work"
LOG_PATH = os.path.join(WORK, "requests.log")


def now_utc():
    return dt.datetime.now(dt.timezone.utc)


def log(msg):
    with open(LOG_PATH, "a") as f:
        f.write(f"{now_utc().isoformat()} {msg}\n")


def parse_retry_after(headers, obj):
    """Seconds to wait, from the Retry-After header and/or the JSON body. Uses the larger."""
    candidates = []
    ra = headers.get("Retry-After")
    if ra is not None:
        try:
            candidates.append(float(ra))
        except ValueError:
            try:
                candidates.append((parsedate_to_datetime(ra) - now_utc()).total_seconds())
            except Exception:
                pass
    if isinstance(obj, dict) and "retry_after" in obj:
        try:
            candidates.append(float(obj["retry_after"]))
        except (TypeError, ValueError):
            pass
    if not candidates:
        return None
    return max(0.0, max(candidates))


class Api:
    def __init__(self):
        self.token = None
        self.tokens_issued = []
        self.counts = collections.Counter()
        self.waits = []

    def _raw(self, method, path, auth):
        headers = {"Accept": "application/json"}
        if auth:
            headers["Authorization"] = "Bearer " + self.token
        data = b"" if method == "POST" else None
        req = urllib.request.Request(BASE + path, data=data, method=method, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, dict(r.headers.items()), r.read()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers.items()), e.read()

    def refresh_token(self):
        _, obj, _ = self.call("POST", "/token", auth=False)
        tok = obj.get("token") if isinstance(obj, dict) else None
        if not isinstance(tok, str) or not tok:
            raise RuntimeError(f"bad token response: {obj!r}")
        self.token = tok
        self.tokens_issued.append(tok)
        log(f"TOKEN new={tok}")

    def call(self, method, path, auth=True, ok_statuses=(200,), max_attempts=300):
        """Repeat the request until it returns an accepted status with valid JSON.

        401 -> fetch a new token; 429 -> wait exactly as instructed; 5xx/network/bad JSON -> retry.
        Any other status is returned to the caller only if listed in ok_statuses, else retried
        a few times and then raised, so nothing is silently dropped.
        """
        unexpected = 0
        for attempt in range(1, max_attempts + 1):
            if auth and self.token is None:
                self.refresh_token()
            try:
                status, headers, body = self._raw(method, path, auth)
            except (urllib.error.URLError, http.client.HTTPException, ConnectionError,
                    socket.timeout, TimeoutError) as e:
                self.counts["network_error"] += 1
                log(f"{method} {path} attempt={attempt} NETWORK_ERROR {e!r}")
                time.sleep(min(0.25 * 2 ** min(attempt, 4), 4))
                continue
            try:
                obj = json.loads(body) if body else None
                json_ok = True
            except ValueError:
                obj, json_ok = None, False
            self.counts[f"{path.split('?')[0].split('/')[1]}:{status}"] += 1
            log(f"{method} {path} attempt={attempt} status={status} bytes={len(body)} json_ok={json_ok} "
                f"retry_after_hdr={headers.get('Retry-After')!r} tok={self.token if auth else '-'} "
                f"head={body[:160]!r}")
            if status in ok_statuses and json_ok:
                return status, obj, headers
            if status == 401:
                self.counts["auth_refresh"] += 1
                self.token = None
                continue
            if status == 429:
                wait = parse_retry_after(headers, obj)
                if wait is None:
                    wait = 1.0
                    self.counts["429_without_wait_hint"] += 1
                self.waits.append(wait)
                time.sleep(wait + 0.05)
                continue
            if status >= 500 or (status == 200 and not json_ok):
                self.counts["server_error_retry"] += 1
                wait = parse_retry_after(headers, obj)
                time.sleep(wait if wait is not None else 0.5)
                continue
            unexpected += 1
            self.counts["unexpected_status"] += 1
            if unexpected >= 5:
                raise RuntimeError(f"{method} {path}: persistent unexpected status {status}: {body[:300]!r}")
            time.sleep(1.0)
        raise RuntimeError(f"{method} {path}: gave up after {max_attempts} attempts")

